 "content": "def transform(grid):
    """Fill each framed left-hand pattern with the color of its matching motif."""
    h, w = len(grid), len(grid[0])
    # The all-zero separator column divides the framed patterns from the motifs.
    split = next(c for c in range(w) if all(grid[r][c] == 0 for r in range(h)))
    # Full-width horizontal separator lines delimit corresponding panels.
    separators = [r for r in range(h) if all(v != 0 for v in grid[r][:split])]
    panels = [(a + 1, b) for a, b in zip(separators, separators[1:])]

    def normalized(points):
        r0 = min(r for r, _ in points)
        c0 = min(c for _, c in points)
        return frozenset((r - r0, c - c0) for r, c in points)

    # Build shape -> color lookup from the colored objects on the right.
    shape_color = {}
    for top, bottom in panels:
        points_by_color = {}
        for r in range(top, bottom):
            for c in range(split + 1, w):
                color = grid[r][c]
                if color:
                    points_by_color.setdefault(color, []).append((r - top, c - split - 1))
        for color, points in points_by_color.items():
            shape_color[normalized(points)] = color

    out = [row[:split] for row in grid]
    for top, bottom in panels:
        holes = [(r - top, c - 1)
                 for r in range(top, bottom)
                 for c in range(1, split - 1)
                 if grid[r][c] == 0]
        color = shape_color.get(normalized(holes)) if holes else None
        if color is not None:
            for r, c in [(r, c) for r in range(top, bottom)
                         for c in range(1, split - 1) if grid[r][c] == 0]:
                out[r][c] = color
    return out


